custom_css:
/* 主题作者：咩野(DC@lambkinling)
请勿二传，二改请标注原作者，倒卖、商用引流司马。
部分代码来自：KAKAA老师的双色盒子、NARIKI、墨千尾，特此感谢。 */

/* 请勿将本主题内任何代码复制并分享至任何服务器或群聊，有需要请移步旅程美化区教程帖 */

/* ----- ❤️‍🔥字体 -----*/
/* 修改URL以及font-family */

/* 信件开头 & 思维链 & 署名 */
@import url("https://fontsapi.zeoseven.com/53/main/result.css");

div[is_user="true"] .mes_text::before,
.mes_block .alignItemsBaseline .name_text,
.mes_block .alignItemsBaseline .timestamp,
.mes_reasoning_header_title::before {
    font-family: "ToneOZ-Tsuipita-TC";
    font-weight: normal;
}

/* 信封封面字体 */
@font-face {
    font-family: "ZSFT-hd";
    src: url("https://fontsapi.zeoseven.com/hd/main.woff2") format("woff2");
    font-display: swap;
}

.mesAvatarWrapper .avatar::before {
    font-family: "ZSFT-hd";
    font-weight: normal;
}

/* ----- 部分变量 ----- */
:root {
  /* 信纸颜色 */
  --paper-color: color-mix(in srgb, var(--SmartThemeChatTintColor) 50%, black);
  /* 信封大小 */
  --letter-height: 175px;
  --letter-width: 330px;
  /* 信封颜色 */
  --letter-user: color-mix(in srgb, var(--SmartThemeUserMesBlurTintColor) 50%, var(--ui-color));
  --letter-char: color-mix(in srgb, var(--SmartThemeBotMesBlurTintColor) 50%, var(--ui-color)); 
  /* 主题色 */
  --theme-color: color-mix(in srgb, var(--SmartThemeShadowColor) 40%, transparent);
  /* 辅助色 */
  --ui-color: black;
  /* 阴影色 */
  --shadow-color: rgba(30, 30, 30, 0.5);
  --em-color: color-mix(in srgb, var(--SmartThemeQuoteColor) 30%, transparent);
  --scrollbar-thumb-color: color-mix(in srgb, var(--theme-color) 90%, transparent);
  /* 边框圆角 */
  --border-radius-small: 3px;
  --border-radius-medium: 5px;
}

/* ----- 文本样式 ------ */
/* 斜体 */
em {
  position: relative;
  display: inline;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.1);
  padding: 0 0.1em;
  line-height: 1.6;
  background-image: 
    linear-gradient(to right, 
  transparent 0%, 
  var(--em-color) 20%, 
  var(--em-color) 80%,
  transparent 100%);
  background-repeat: repeat-x;
  background-position: 0 70%;
  background-size: 100% 0.6em; /* 调整背景线粗细*/
  text-shadow: none;
}

/* 代码块 */
code {
  border: none;
  border-radius: 5px;
  background: var(--em-color) !important;
  color: var(--SmartThemeBodyColor) !important;
  box-shadow: 1px 1px 3px var(--SmartThemeUnderlineColor);
  line-height: 1.6;
}

.hljs {
  border: none;
  background: var(--em-color) !important;
}

/* 删除文本 */
del, s {
  color: red;
  font-style: italic;
  text-decoration: underline wavy currentColor 0.08em;
  text-underline-offset: 2px;
}

/* MD引用文本 */
blockquote {
  border-color: var(--SmartThemeBorderColor) !important;
  background: 
    linear-gradient(to right,
    var(--SmartThemeUnderlineColor),
    transparent) !important;
}

/* --- 滚动条 --- */
::-webkit-scrollbar {
  display: none;
}

html {
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb-color) #f1f1f1;
}

/* --- 滑动条 --- */
input[type="range"] {
  background: var(--scrollbar-thumb-color) !important;
  filter: none !important;
  box-shadow: none !important;
}

input[type="range"]::-webkit-slider-thumb {
  background: var(--theme-color);
  border: 3px double var(--SmartThemeBorderColor);
  filter: none !important;
  box-shadow: none !important;
}

/* 滑动条滑块 */
input[type="range"]::-webkit-slider-thumb {
  width: 30px;
  height: 30px; 
  background-image: url('https://i.postimg.cc/L5JskjkL/11-20250720222229.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-color: transparent !important;
  border: none;
  cursor: pointer;
  transition: transform 0.3s ease;
}

/* ----- 聊天区域 ------ */
/* --- 思维链 --- */
.mes_reasoning_header_title::before {
  content: "尊敬的咩野大王:"; /* ❤️‍🔥文字自定义 */
  white-space: pre;
  font-size: calc(var(--mainFontSize) * 1.1); /* 大小 */
  border-bottom: 1.5px dashed var(--SmartThemeQuoteColor);

}

.mes_reasoning_header_title {
  font-size: 0;
}

.mes_reasoning_arrow.fa-chevron-up {
  display: none;
}

.mes_reasoning_header {
  background: transparent;
  padding: 0;
  padding-left: 3px;
  box-shadow: none;
  border-radius: 1px;
}

/* ❤️‍🔥User - 开头自定义文字 */
div[is_user="true"] .mes_text::before {
  content: "见字如面，见信如晤:";
  position: absolute;
  top: 20px;
  text-shadow: none;
  font-size: calc(var(--mainFontSize) * 1.1); /* 大小 */
}

/* --- 聊天窗 --- */
#form_sheld {
  margin: 0px auto !important;
}

#chat {
  flex-direction: column;
  align-items: center;
  background: transparent;
  border: none;
}

/* --- 消息框 --- */
.mes {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--paper-color);
  box-shadow: 0px 0px 6px 3px var(--shadow-color);
  width: 95%; /* 宽度 */
  margin: 20px auto;
  padding: 10px 0 30px;
}

/* 纸张堆叠效果 */
.mes:before, 
.mes:after {
  content: "";
  position: absolute;
  z-index: -1;
  background-color: var(--paper-color);
  box-shadow: 0 0 6px 2px var(--shadow-color);
  transform-origin: center center;
}

/* AI - 纸张倾斜 */
div[is_user="false"].mes::before,
div[is_user="false"].mes::after {
  height: 100%;
  width: 100%;
}

div[is_user="false"].mes::before {
  left: -1px;
  top: -4px;
  -webkit-transform: rotate(0.2deg);
  transform: rotate(0.2deg);
}
div[is_user="false"].mes::after {
  left: 2px;
  top: -5px;
  -webkit-transform: rotate(-0.3deg);
  transform: rotate(-0.3deg);
}

/* 用户 - 纸张倾斜 */
div[is_user="true"].mes::before,
div[is_user="true"].mes::after {
  height: 100%;
  width: 101%;
}

div[is_user="true"].mes::before {
  left: -4px;
  top: 4px;
  transform-origin: center center;
  -webkit-transform: rotate(-2.5deg);
  transform: rotate(-2.5deg);
}

div[is_user="true"].mes:after {
  left: -3px;
  top: -6px;
  transform-origin: center center;
  -webkit-transform: rotate(-1.5deg);
  transform: rotate(-1.5deg);
}

/* 文本框 */
.mes_block {
  position: relative;
  padding: 0 7px;
  overflow: visible;
  justify-content: center;
}

/* 文本(横线颜色) */
.mes_text{
  background:
    linear-gradient(rgba(255, 255, 255, 0.1) 7%, transparent 0%) 0 0 / 18px 18px;
  padding: 0 5px 48px !important;
  margin: 0;
  text-align: justify;
}

div[is_user="true"] .mes_text {
  margin-top: 20px !important;
}

/* 名字 & 时间戳 */
.mes_block .flex-container.alignItemsBaseline {
  position: absolute;
  bottom: 0;
  right: 10px;
  display: grid;
  grid-template-columns: auto auto;
  grid-template-rows: auto auto;
  justify-items: end;
  align-items: center;
  gap: 1px 5px;
  color: var(--SmartThemeBodyColor);
  font-size: calc(var(--mainFontSize) * 1.1); /* 字体大小 */
}

/* 名字 */
.alignItemsBaseline .name_text {
  grid-row: 1;
  grid-column: 1;
}

/* ❤️‍🔥char名字前自定义文案 */
.mes_block .name_text::before {
  content: "From:";
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  color: inherit;
  margin-right: 2px;
}

/* 幽灵图标 */
.alignItemsBaseline .mes_ghost {
  grid-row: 1;
  grid-column: 2;
}

/* 时间戳 */
.alignItemsBaseline .timestamp {
  grid-row: 2;
  grid-column: 1;
  justify-self: end;
  font-size: inherit;
  color: inherit;
}

/* 模型图标 */
.alignItemsBaseline .icon-svg.timestamp-icon {
  grid-row: 2;
  grid-column: 2;
}

/* last mes */
.last_mes {
  margin-bottom: 20px !important;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0;
}

div[is_user="false"].last_mes {
  padding-bottom: 50px;
}

/* ai消息左右箭头 */
.swipe_left,
.swipe_right {
  opacity: 1 !important; /* 箭头透明度 */
  color: var(--SmartThemeBotMesBlurTintColor);
}

.last_mes .swipeRightBlock {
  margin-right: 15px;
}

/* 编辑按钮 */
.mes_button,
.mes_edit_buttons,
.mes .extraMesButtons {
  filter: none !important;
  box-shadow: none !important;
  font-size: var(--mainFontSize);
  opacity: 1 !important;
}

div[is_user="true"] .mes_buttons {
  color: var(--SmartThemeUserMesBlurTintColor);
}

div[is_user="false"] .mes_buttons {
  color: var(--SmartThemeBotMesBlurTintColor);
}

/* --- 头像区域(信封渐变) --- */
.mesAvatarWrapper {
  display: flex;
  align-items:end;
  justify-content: center;
  position: relative;
  margin: 10px 0;
  padding: 0;
  width: var(--letter-width);
  height: var(--letter-height);
  background: 
    linear-gradient(to top,
  var(--letter-user) 0%,
  var(--ui-color) 75%);
  box-shadow: 
    2px 2px 4px 2px var(--shadow-color),
    inset -0.8px -0.8px 2px 1px  var(--shadow-color);
  transform-origin: center center;
  transform: rotate(-5deg);
}

div[is_user="false"] .mesAvatarWrapper {
    background: 
      linear-gradient(to top,
  var(--letter-char) 0%,
  var(--ui-color) 75%);
}

/* 信封封口效果 */
.mesAvatarWrapper::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: var(--letter-width);
  height: var(--letter-height);
  clip-path: polygon(0% 0%, 100% 0, 100% 10%, 50% 35%, 0 10%);
  background: 
     linear-gradient(to bottom,
  var(--letter-user) 0%,
  var(--ui-color) 50%);
}

div[is_user="false"] .mesAvatarWrapper::before {
  background: linear-gradient(to bottom,
  var(--letter-char) 0%,
  var(--ui-color) 50%);
}

/* 封口阴影 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  width: calc(var(--letter-width) + 2px);
  height: calc(var(--letter-height) + 4px);
  clip-path: polygon(0% 0%, 100% 0, 100% 10%, 50% 35%, 0 10%);
  top: 0;
  left: -1px;
  z-index: -2;
  background: var(--shadow-color);
  filter: blur(10px) !important;
}

/* 头像容器 */
.mesAvatarWrapper .avatar {
  display: flex;
  position: relative;
  pointer-events: none !important;
  transform: rotate(5deg) !important;
}

/* ❤️‍🔥信封自定义文字 - 用户 */
.mesAvatarWrapper .avatar::before {
  content: "Sealed with a Kiss";
  white-space: pre;
  position: absolute;
  right:8%; /* 位置 */
  bottom: 120%;
  font-size: calc(var(--mainFontSize) * 1.2); /* 字体大小 */
  background:
    linear-gradient(to right, #ab8018, #eddf94, #b37e18, #c89923);
  color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-transform: rotate(-8deg) !important;
  text-shadow: none;
  transform: rotate(-8deg) !important;
}

/* ❤️‍🔥信封自定义文字 - char */
div[is_user="false"] .mesAvatarWrapper .avatar::before {
  content: "To My Moon and Stars,\A I remain, as ever, Yours.";
  right:5%;
  bottom: 100%;
  font-size: calc(var(--mainFontSize) * 1);
}

/* --- 头像图片 --- */
.mes .mesAvatarWrapper .avatar img {
  position: absolute;
  left: 13%; /* ❤️‍🔥头像位置(left&bottom) */
  bottom: 8px;
  -webkit-transform: rotate(7deg) scale(2);
  transform: rotate(7deg) scale(2); /* 头像大小 */
  pointer-events: auto;
  border-radius: 0px !important;
  outline: 1px inset var(--letter-user);
  box-shadow: 1px 1px 2px 1px var(--shadow-color);
}

div[is_user="false"] .mesAvatarWrapper .avatar img {
  outline-color: var(--letter-char);
}

/* 自定义图片 */
.mesAvatarWrapper .avatar::after {
  content: "";
  position: absolute;
  z-index: -1;
  bottom: 30px;
  left: 7%;
  width: 50px;
  height: 50px;
  -webkit-transform: rotate(-10deg) scale(2);
  transform: rotate(-10deg) scale(2);
/* ❤️‍🔥头部自定义图片 - User */
  background: url('https://i.postimg.cc/c4vP7pcJ/Oplus-Info-Collection-250707042158698.png');
  background-size: contain;
  outline: 1px inset var(--letter-char);
  box-shadow: -1px -1px 5px var(--shadow-color);
}

/* ❤️‍🔥头部自定义图片 - Char */
div[is_user="false"] .mesAvatarWrapper .avatar::after {
  background: url('https://i.postimg.cc/L5XwbwKN/Oplus-Info-Collection-250707042150502.png');
  background-size: contain;
  outline-color: var(--letter-user);
}

/* --- 楼层、计时器、tokens --- */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: none;
  position: relative;
  transform: rotate(5deg) !important;
  margin-bottom: 5px;
  margin-right: 5px;
  padding: 0px 3px;
  border: 1px solid currentColor;
  border-radius: 10px;
  color: var(--SmartThemeQuoteColor);
  pointer-events: auto !important;
}

/* 爱心 */
.mesIDDisplay:before,
.mes_timer:before,
.tokenCounterDisplay:before {
  content: "";
  display: inline-block;
  width: 1em;
  height: 1em;
  margin: 0 1px 0 2px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 24 24"><path fill="%23ff0000" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>');
  background-size: contain;
}

/* 悬停 */
.mesAvatarWrapper:hover .mesIDDisplay,
.mesAvatarWrapper:hover .mes_timer,
.mesAvatarWrapper:hover .tokenCounterDisplay {
  display: flex !important;
  align-items: center;
  position: relative;
}

div[is_user="true"] .mesAvatarWrapper .mes_timer,
.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty {
  display: none !important;
}

/* ----- 菜单抽屉 ------ */
/* 全局头像 */
.avatar img,
body.big-avatar .avatar img{
  box-shadow: none;
  border: none;
}

/* 缩小锁定图标 */
#rm_button_characters,
#rm_button_panel_pin_div,
#lm_button_panel_pin_div,
#WI_button_panel_pin_div {
  font-size: calc(var(--mainFontSize) * 1.2);
}

/* 反代警告 */
.reverse_proxy_warning {
  background-color: transparent !important;
}

/* API标题特殊处理 */
#title_api {
  padding-bottom: 0; 
}

/* OpenAI范围块样式 */
#range_block_openai .range-block .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

label[for="openai_image_inlining"] + div,
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  text-align: left;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin-right: 5px;
}

/* 抽屉页 */
.drawer-content {
  box-shadow: none !important;
  border: none;
  border-radius: var(--border-radius-small);
}

#AdvancedFormatting h3.flex-container {
  flex-wrap: nowrap;
}

/* --- 标题栏 --- */
.standoutHeader,
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#top-settings-holder h4:not(#ai-config-button):not(#rightNavHolder),
#user-settings-block h4, 
.standoutHeader {
  background-image:
    linear-gradient(90deg, var(--theme-color) 50%, transparent 50%),
    linear-gradient(180deg, var(--theme-color) 50%, transparent 50%);
  background-size: 10px 10px;
  border-radius: var(--border-radius-small);
  border-bottom: 2px solid var(--SmartThemeBorderColor);
  border-right: 1.5px solid var(--SmartThemeBorderColor);
  margin-bottom: 5px;
}

/* 箭头 */
.inline-drawer-icon {
  color: var(--SmartThemeBorderColor);
  font-size: calc(var(--mainFontSize) * 1.2);
  padding-right: 3px;
}

.standoutHeader,
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
  filter: none !important;
  -webkit-filter: none !important;
}

/* 正则防误操作 */
#saved_regex_scripts, 
#saved_scoped_scripts {
  padding-right: 40px; 
}

.regex_script_name.flexGrow.overflow-hidden {
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}

/* 拓展页输入助手 */
.integrated-button-row {
  background: transparent !important;
  padding: 1px 7px!important;
}

/* --- 按钮 --- */
.menu_button:not(.mes_edit_buttons *) {
  background: var(--theme-color);
  border-radius: var(--border-radius-small);
  filter: none !important;
  box-shadow: none !important;
  color: var(--SmartThemeBorderColor);
}

/* 警告按钮 */
#ddelete_button,
#dialogue_del_mes_ok,
#dialogue_popup_ok,
#bulk_tag_popup_reset,
#bulk_tag_popup_remove_mutual,
.mes_edit_cancel.menu_button,
.menu_button.popup-button-ok,
.redWarningBG {
  background: rgba(150, 0, 0) !important;
  color: black !important;
}

/* --- 勾选框 --- */
input[type="checkbox"] {
  background: 
    color-mix(in srgb, var(--SmartThemeBorderColor) 45%, transparent);
  filter: none !important;
  box-shadow: none !important;
  outline: none;
  -webkit-transform: scale(0.85);
  transform: scale(0.85);
}

.checkbox_label {
  display: flex;
  align-items: center;
}

/* 勾选框选中状态 */
input[type="checkbox"]:checked {
  background: var(--theme-color) !important;
  border: 1px solid var(--ui-color);
  outline: 1px solid var(--SmartThemeBorderColor);
}

/* --- 下拉框 --- */
select {
  background: 
    linear-gradient(to left, 
    var(--SmartThemeChatTintColor) 0%, 
    var(--SmartThemeBlurTintColor) 100%);
  outline: none !important;
  filter: none !important;
  box-shadow: none;
}

/* --- 输入框 --- */
input[type="text"],
input[type="number"],
input[type="switch"],
input:not([type]),
textarea:not([type="search"]){
  background: var(--ui-color);
  border: 1.2px solid var(--SmartThemeBorderColor);
  outline: none !important;
}

input[type="number"] {
  background: transparent;
}

input[type="text"]:focus,
input[type="number"]:focus,
input[type="switch"]:focus,
input:not([type]):focus,
textarea:not([type="search"]):not(#send_form textarea):focus {
  border-style: dashed;
  border-width: 1.5px;
  background: 
    linear-gradient(to bottom right, 
    var(--SmartThemeBlurTintColor) 0%, 
    var(--SmartThemeChatTintColor) 100%);
}

/* 特殊文本输入框 */
.text_pole:not(.objective-task) {
  background: 
   linear-gradient(135deg, 
   var(--SmartThemeBlurTintColor) 0%, 
   var(--SmartThemeChatTintColor) 100%);
}

/* --- 弹窗 --- */
#character_popup, 
#dialogue_popup,
.draggable,        
#select_chat_popup, 
.popup:not(.transparent_dialogue_popup) {  
  border-radius: var(--border-radius-small);
}

/* 对话弹出窗文本 */
#dialogue_popup_text {
  padding-right: 10px; 
}

/* 给'提示词拆分'添加滚动条 */
.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
  padding-right: 10px;
}

/* 通知提示框 */
div.toast.toast-success {
  background-color: color-mix(in srgb, var(--SmartThemeShadowColor) 85%, black) !important;
  border-radius: var(--border-radius-small) !important;
  color: var(--SmartThemeBodyColor) !important;
  border: 2px solid var(--ui-color);
  box-shadow: 0 2px 6px  var(--shadow-color) !important;
}

/* --- 预设页 --- */
/*提示词管理器 */
#completion_prompt_manager {
  width: 100%;
}

#completion_prompt_manager_list .completion_prompt_manager_list_separator {
  display: none !important;
}

/* 提示词 & 总词符数 */
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  filter: none;
}

#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeQuoteColor) !important;
  padding: 0;
}

.completion_prompt_manager_footer {
  padding: 0px !important;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
  margin-left: 0;
}

/* 去除阴影 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt
span
span
span {
  filter: none !important;
}

/* 预设词条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  border-radius: var(--border-radius-small);
  border: none;
  outline: 2px solid var(--theme-color);

}

/* 未启用条目 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  background: var(--ui-color);
  outline: none !important;
  box-shadow: none !important;
  opacity: 0.4;
}

/* 未启用条目的字体颜色 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action, #completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
  color: var(--SmartThemeQuoteColor);
}

/* 滑块设置区内边距 */
#completion_prompt_manager .range-block .text_pole {
  padding: 0 15px 10px 15px;
}

/* --- 世界书 --- */
#WorldInfo {
  margin-top: var(--top-distance);
}
/* 弹出窗口（iOS特定样式)  */
@supports (-webkit-touch-callout: none) {
  #world_popup {
    margin-top: 0;
    width: 100%;
  }
}

/* 世界书条目 */
.world_entry {
  margin-top: 8px;
  background: transparent;
}

/* 世界书条目卡片 */
.wi-card-entry {
  border-radius: var(--border-radius-small);
  border: 1px solid var(--ui-color);
  outline: 1px solid var(--theme-color);
  background: transparent;
}
@media screen and (max-width: 1000px) {
  .world_entry_form .inline-drawer-header  {
  border-radius: var(--border-radius-small);
  border: none;
  outline: none;
  background: transparent !important;
}

/* 世界书表单控件 */
.world_entry_form_control {
  margin: 0;
  background: transparent;
}

/* 世界书选择器选项 */
.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
  background: transparent;
}

/* 世界书选择器移除按钮 */
span.select2.select2-container .select2-selection__choice__remove,
.select2_choice_clickable_buttonstyle
  +span.select2-container
  .select2-selection__choice__display {
  line-height: 1.5;
  background-color: transparent;
  margin: 0px;
}
.select2-container
  .select2-selection--multiple
  .select2-selection__choice__remove {
  padding: 0 5px;
}

/* 单击展开 */
.inline-drawer-content {
  background: transparent !important;
}

/* --- 图库 --- */
#form_bg_download .bg_example.add_bg_but.interactable{
  opacity: 0.5 !important;
  background-color: var(--theme-color);
}

.bg_example {
  box-shadow: none;
}

/* --- 用户管理器 --- */
.avatar-container{
  border: 1px dotted var(--SmartThemeBorderColor);
  border-radius: var(--border-radius-small);
}

/* 选中的用户 */
.avatar-container.selected{
  background: var(--SmartThemeChatTintColor);
  border: 2px solid var(--SmartThemeBorderColor);
}

#movingUIPresets{
  margin-bottom: 0 !important;
}

/* --- 角色管理器 --- */
#CharListButtonAndHotSwaps {
  margin-bottom: calc(var(--mainFontSize) * 0.8);
}

label[for="char-management-dropdown"] {
  width: 100%;
}

#avatar_div {
  flex-direction: column;
}

#avatar_controls {
  align-items: center;
}

.character_select {
  margin-top: calc(var(--mainFontSize) * 0.8);
}

/* 星标角色卡 */
.character_select.is_fav .avatar {
  outline: 2px solid var(--SmartThemeQuoteColor);
}

.character_select.is_fav .ch_name {
  color: var(--SmartThemeQuoteColor);
}

.tag.excluded::after {
  font-size: calc(var(--mainFontSize) * 2);
}

.tag.actionable {
  font-size: calc(var(--mainFontSize) * 1);
  min-height: calc(var(--mainFontSize) * 2);
  min-width: calc(var(--mainFontSize) * 2);
}

/* 角色收藏区滚动条 */
#HotSwapWrapper {
  overflow: hidden;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  height: calc(var(--avatar-base-height) + 16px);
  max-height: calc(var(--avatar-base-height)* 2);
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-thumb-color);
}

.avatars_inline {
  gap: 5px; /* 头像间距 */
  flex-wrap: nowrap;
  overflow: visible;
}

/* ----- 底栏 & 顶栏 ------ */
/* 列表 */
.list-group,
.options-content,
#options {
  box-shadow:none !important;
}

/* 底栏输入框 */
#send_form textarea{
  clip-path: none !important;
  background: color-mix(in srgb, var(--ui-color) 60%, transparent);
  margin-bottom: 1px;
  border-radius: var(--border-radius-small);
  border: 0.1px solid var(--ui-color);
}

/* 顶栏 & 底栏背景*/
#top-bar,
body.no-blur #top-bar,
#send_form,
body.no-blur #send_form {
  background-image:
    linear-gradient(90deg, var(--theme-color) 50%, transparent 50%),
    linear-gradient(180deg, var(--theme-color) 50%, transparent 50%);
  background-size: 10px 10px;
  outline: none !important;
  box-shadow: none;
}

#send_form,
body.no-blur #send_form {
  border-radius: var(--border-radiussmall);
  border: none !important;
  outline: none !important;
}

/* 顶栏 & 底栏图标 */
.drawer-icon.fa-fw,
#send_form .fa-solid,
#quick-reply-rocket-button {
  opacity: 0.65 !important;
  font-size: calc(var(--mainFontSize) * 1.2); /* 大小 */
  text-shadow: none !important;
  color: var(--SmartThemeBorderColor);
  display: flex;
  overflow: visible;
  justify-content: center;
}

/* 悬停效果 */
#send_form .fa-solid:hover,
#quick-reply-rocket-button:hover,
.drawer-icon.fa-fw:hover {
  opacity: 1 !important;
  -webkit-transform: translateY(-2px);
  transform: translateY(-2px);
  transition: all 0.2s ease-in-out;
  color: var(--SmartThemeQuoteColor);
}

/* 顶栏图标样式 */
.drawer-icon.fa-fw {
  overflow: visible;
  position: relative;
  z-index: 1;
  opacity: 1;
  transform-origin: center;
  height: 28px;
  width: 28px;  /* 图标大小 */
  display: flex;
  justify-content: center;
  align-items: center;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  transition: all 0.3s ease;
}

/* 底栏图标按钮 */
#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
  opacity: 1;
  width: 36px;
  height: 36px;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  -webkit-transition: all 0.3s ease;
  transition: all 0.3s ease; 
  position: relative; 
  -webkit-filter: none !important; 
  filter: none !important; 
}

/* 隐藏原有的FontAwesome图标 */
.drawer-icon.fa-fw::before {
  content: '' !important;
  font-size: 0 !important;
}

